            print(f"You chose paper, I chose rock. Paper covers rock, you win!")
        elif computer_choice == "scissors":
            print(f"You chose paper, I chose scissors. Scissors cut paper, I win!")
    elif user_choice == "scissors":
        if computer_choice == "rock":
            print(f"You chose scissors, I chose rock. Rock breaks scissors, I win!")
        elif computer_choice == "paper":
            print(f"You chose scissors, I chose paper. Scissors cut paper, you win!")

    # Play again?
    restart = input("Do you want to play again? (yes/no): ").lower()
    while restart not in ["yes", "no"]:
        print("Invalid response. Please enter 'yes' or 'no'.")
